```css
/* CSS PART 1 OF 2 */

:root {
  --ink: #202b30;
  --ink-soft: #526168;
  --navy: #243b45;
  --navy-deep: #192d35;
  --orange: #d8753d;
  --orange-dark: #b85b2b;
  --cream: #f6f3ed;
  --paper: #fffefa;
  --stone: #e8e4dc;
  --line: #d8d4cc;
  --white: #ffffff;
  --font-heading: "DM Sans", sans-serif;
  --font-body: "Inter", sans-serif;
  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --radius: 5px;
  --shadow: 0 16px 45px rgba(25, 45, 53, .12);
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, textarea, select {
  font: inherit;
}

button, a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

h1, h2, h3, p {
  margin-top: 0;
}

h1, h2, h3 {
  color: var(--navy-deep);
  font-family: var(--font-heading);
  font-weight: 750;
  letter-spacing: -.045em;
  line-height: 1.12;
}

h1 {
  font-size: clamp(2.8rem, 6vw, 5.5rem);
}

h2 {
  font-size: clamp(2rem, 4vw, 3.35rem);
}

h3 {
  font-size: 1.35rem;
}

p {
  color: var(--ink-soft);
}

.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 10vw, 130px);
}

.section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--orange-dark);
  font-size: .75rem;
  font-weight: 800;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.section-kicker::before {
  width: 30px;
  height: 2px;
  background: var(--orange);
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 24px;
}

.section-intro {
  max-width: 650px;
  font-size: 1.05rem;
}

/* Header and navigation */

.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  width: 62px;
  height: 62px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand-name {
  color: var(--navy-deep);
  font-family: var(--font-heading);
  font-size: .94rem;
  font-weight: 800;
  letter-spacing: -.025em;
}

.brand-description {
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: .67rem;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.5vw, 34px);
}

.primary-nav a:not(.button) {
  color: var(--ink);
  font-size: .85rem;
  font-weight: 650;
  transition: color .2s ease;
}

.primary-nav a:not(.button):hover {
  color: var(--orange-dark);
}

.header-phone {
  white-space: nowrap;
}

/* Buttons */

.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 13px 23px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--orange);
  color: var(--white);
  font-size: .9rem;
  font-weight: 750;
  line-height: 1.3;
  text-align: center;
  transition: background .2s ease, transform .2s ease;
  cursor: pointer;
}

.button:hover {
  transform: translateY(-2px);
  background: var(--orange-dark);
}

.button-dark {
  background: var(--navy);
}

.button-dark:hover {
  background: var(--navy-deep);
}

.button-outline {
  border-color: rgba(255,255,255,.65);
  background: transparent;
  color: var(--white);
}

.button-outline:hover {
  background: var(--white);
  color: var(--navy-deep);
}

/* Hero */

.hero {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-inner {
  display: grid;
  min-height: 650px;
  grid-template-columns: 1.02fr .98fr;
  align-items: center;
  gap: clamp(35px, 6vw, 85px);
  padding-block: 76px;
}

.hero-copy {
  position: relative;
  z-index: 2;
  max-width: 650px;
}

.hero .section-kicker {
  color: #f0a477;
}

.hero h1 {
  margin-bottom: 25px;
  color: var(--white);
}

.hero h1 em {
  color: #eda16f;
  font-style: normal;
}

.hero-description {
  max-width: 535px;
  margin-bottom: 32px;
  color: #d2dce0;
  font-size: clamp(1rem, 1.4vw, 1.15rem);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 34px;
  color: #c7d2d6;
  font-size: .83rem;
}

.hero-note::before {
  width: 28px;
  height: 1px;
  background: var(--orange);
  content: "";
}

.hero-visual {
  position: relative;
  min-width: 0;
}

.hero-image {
  width: 100%;
  height: 510px;
  border-radius: 3px;
  object-fit: cover;
  object-position: center;
}

.hero-visual::after {
  position: absolute;
  right: -14px;
  bottom: -14px;
  z-index: -1;
  width: 65%;
  height: 65%;
  border-right: 2px solid var(--orange);
  border-bottom: 2px solid var(--orange);
  content: "";
}

.hero-stamp {
  position: absolute;
  right: -24px;
  top: 30px;
  padding: 17px 22px;
  background: var(--orange);
  color: var(--white);
  font-size: .77rem;
  font-weight: 800;
  letter-spacing: .08em;
  line-height: 1.5;
  text-align: center;
  text-transform: uppercase;
}

/* Company credentials */

.credentials {
  background: var(--cream);
  border-bottom: 1px solid var(--line);
}

.credentials-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;
}

.credential {
  padding: 29px 32px;
  border-right: 1px solid var(--line);
}

.credential:first-child {
  padding-left: 0;
}

.credential:last-child {
  border-right: 0;
}

.credential strong {
  display: block;
  margin-bottom: 3px;
  color: var(--navy);
  font-family: var(--font-heading);
  font-size: 1.45rem;
  font-weight: 800;
  letter-spacing: -.04em;
}

.credential span {
  color: var(--ink-soft);
  font-size: .83rem;
}

/* Why choose us */

.why-section {
  background: var(--paper);
}

.why-layout {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.why-copy {
  position: sticky;
  top: 35px;
}

.why-copy p {
  max-width: 460px;
}

.why-list {
  border-top: 1px solid var(--line);
}

.why-item {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 22px;
  padding: 29px 0;
  border-bottom: 1px solid var(--line);
}

.why-number {
  color: var(--orange-dark);
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 800;
}

.why-item h3 {
  margin-bottom: 9px;
}

.why-item p {
  max-width: 510px;
  margin-bottom: 0;
  font-size: .94rem;
}

/* Roofing and restoration */

.roof-section {
  background: var(--cream);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(40px, 7vw, 90px);
}

.roof-photo {
  width: 100%;
  height: 570px;
  object-fit: cover;
  object-position: center;
}

.roof-copy h2 {
  margin-bottom: 23px;
}

.roof-copy > p {
  margin-bottom: 28px;
}

.roof-points {
  display: grid;
  gap: 0;
  margin: 0 0 32px;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--line);
}

.roof-points li {
  position: relative;
  padding: 15px 0 15px 27px;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: .94rem;
}

.roof-points li::before {
  position: absolute;
  left: 0;
  color: var(--orange-dark);
  font-weight: 900;
  content: "✓";
}

/* Project portfolio */

.projects-section {
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 42px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 25px;
}

.project-card {
  min-width: 0;
  background: var(--cream);
}

.project-card:first-child {
  grid-row: span 2;
}

.project-image {
  width: 100%;
  height: 290px;
  object-fit: cover;
  transition: transform .45s ease;
}

.project-card:first-child .project-image {
  height: 100%;
  min-height: 600px;
}

.project-media {
  overflow: hidden;
}

.project-card:hover .project-image {
  transform: scale(1.025);
}

.project-caption {
  padding: 21px 24px;
}

.project-caption h3 {
  margin-bottom: 5px;
}

.project-caption p {
  margin-bottom: 0;
  font-size: .83rem;
}

.project-card:first-child .project-media {
  height: calc(100% - 96px);
}

/* Reduced motion */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *, *::before, *::after {
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}
