/* CSS PART 2 OF 2 */

/* Contact and conversion */

.contact-section {
  padding-block: clamp(75px, 9vw, 115px);
  background: var(--navy-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(40px, 8vw, 100px);
  align-items: start;
}

.contact-copy .section-kicker {
  color: #f0a477;
}

.contact-copy h2 {
  margin-bottom: 22px;
  color: var(--white);
}

.contact-copy > p {
  max-width: 430px;
  color: #cbd6da;
}

.contact-links {
  display: grid;
  gap: 13px;
  margin-top: 35px;
}

.contact-link {
  display: flex;
  align-items: center;
  gap: 13px;
  color: var(--white);
  font-weight: 700;
}

.contact-link:hover {
  color: #f0a477;
}

.contact-link-icon {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(255,255,255,.3);
  border-radius: 50%;
  color: #f0a477;
}

.contact-form-wrap {
  padding: clamp(25px, 4vw, 43px);
  border-radius: var(--radius);
  background: var(--paper);
  box-shadow: var(--shadow);
}

.contact-form-wrap h3 {
  margin-bottom: 8px;
  font-size: 1.65rem;
}

.form-intro {
  margin-bottom: 27px;
  font-size: .9rem;
}

.contact-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 19px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy);
  font-size: .83rem;
  font-weight: 750;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: var(--white);
  color: var(--ink);
  font-size: .94rem;
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #818b8e;
}

.contact-submit {
  width: 100%;
  grid-column: 1 / -1;
  margin-top: 5px;
}

.form-disclaimer {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--ink-soft);
  font-size: .76rem;
}

/* Footer */

.site-footer {
  padding-block: 40px;
  background: #14252c;
  color: var(--white);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.footer-brand .brand-logo {
  width: 48px;
  height: 48px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: #b7c3c7;
}

.footer-details {
  color: #b7c3c7;
  font-size: .82rem;
  text-align: right;
}

.footer-details a {
  color: var(--white);
}

.footer-details a:hover {
  color: #f0a477;
}

/* Accessible navigation toggle */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: transparent;
  color: var(--navy);
  cursor: pointer;
}

/* Tablet */

@media (max-width: 980px) {
  :root {
    --gutter: 32px;
  }

  .header-inner {
    min-height: 78px;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a:not(.button) {
    font-size: .78rem;
  }

  .header-phone {
    padding-inline: 15px;
    font-size: .8rem;
  }

  .hero-inner {
    min-height: 560px;
    gap: 35px;
  }

  .hero-image {
    height: 430px;
  }

  .hero-stamp {
    right: -10px;
  }

  .why-layout,
  .roof-layout,
  .contact-layout {
    gap: 40px;
  }

  .roof-photo {
    height: 480px;
  }

  .projects-grid {
    gap: 18px;
  }
}

/* Mobile navigation and layout */

@media (max-width: 760px) {
  :root {
    --gutter: 23px;
  }

  .section {
    padding-block: 72px;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
  }

  .brand-logo {
    width: 51px;
    height: 51px;
  }

  .brand-name {
    font-size: .82rem;
  }

  .brand-description {
    font-size: .59rem;
  }

  .menu-toggle {
    display: inline-flex;
    flex: 0 0 auto;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% + 1px);
    right: 0;
    left: 0;
    display: none;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 12px var(--gutter) 22px;
    border-bottom: 1px solid var(--line);
    background: var(--paper);
    box-shadow: 0 14px 22px rgba(25,45,53,.09);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
    font-size: .95rem;
  }

  .primary-nav .button {
    margin-top: 15px;
  }

  .hero-inner {
    grid-template-columns: 1fr;
    gap: 38px;
    padding-block: 68px 65px;
  }

  .hero-copy {
    max-width: 600px;
  }

  .hero h1 {
    font-size: clamp(2.8rem, 11vw, 4.4rem);
  }

  .hero-image {
    height: min(430px, 85vw);
  }

  .hero-stamp {
    right: 10px;
    top: 15px;
  }

  .credentials-inner {
    grid-template-columns: 1fr;
    padding-block: 8px;
  }

  .credential,
  .credential:first-child {
    padding: 17px 0;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .credential:last-child {
    border-bottom: 0;
  }

  .credential strong {
    font-size: 1.3rem;
  }

  .why-layout,
  .roof-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .why-copy {
    position: static;
  }

  .why-item {
    grid-template-columns: 42px 1fr;
    gap: 14px;
    padding-block: 23px;
  }

  .roof-photo {
    height: min(430px, 90vw);
    order: 2;
  }

  .roof-copy {
    order: 1;
  }

  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
    margin-bottom: 28px;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .project-card:first-child {
    grid-row: auto;
  }

  .project-card:first-child .project-media {
    height: auto;
  }

  .project-card:first-child .project-image,
  .project-image {
    height: min(380px, 78vw);
    min-height: 0;
  }

  .contact-layout {
    gap: 35px;
  }

  .contact-form-wrap {
    padding: 25px 20px;
  }

  .footer-inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 22px;
  }

  .footer-details {
    text-align: left;
  }
}

/* Narrow mobile */

@media (max-width: 480px) {
  :root {
    --gutter: 19px;
  }

  body {
    font-size: 15px;
  }

  h2 {
    font-size: 2.15rem;
  }

  .hero-inner {
    padding-block: 55px;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    align-items: flex-start;
    font-size: .77rem;
  }

  .hero-stamp {
    padding: 11px 14px;
    font-size: .67rem;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 15px;
  }

  .form-field-full,
  .contact-submit,
  .form-disclaimer {
    grid-column: 1;
  }

  .contact-form-wrap {
    padding: 23px 17px;
  }

  .brand {
    gap: 9px;
  }

  .brand-name {
    max-width: 195px;
    font-size: .76rem;
  }

  .brand-description {
    font-size: .54rem;
  }

  .project-caption {
    padding: 17px;
  }
}

/* Visible keyboard focus */

:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

.primary-nav a:focus-visible,
.button:focus-visible,
.menu-toggle:focus-visible,
.contact-link:focus-visible {
  outline-color: var(--orange);
  outline-offset: 4px;
}

/* Reduced motion */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}
